"""Generate nle_shim_data/codehack_tables.py: the object and monster fields CodeHack reads.

The data comes from the engine library's static template tables (nh_tmpl_mons,
nh_tmpl_objects, nh_tmpl_obj_descr), never from a game's own arrays, whose object
descriptions are shuffled.

Run in the game image:
    python vendor/tools/gen_codehack_tables.py vendor/nle_shim_data/codehack_tables.py
"""

import ctypes as C
import pathlib
import sys
import textwrap

from nethack_core import _engine, glyphs

sys.path.append(str(pathlib.Path(__file__).resolve().parents[1]))
from nle_shim_data.objects_table import OBJECT_TABLE  # noqa: E402


class _Attack(C.Structure):
    _fields_ = [(f, C.c_ubyte) for f in ("aatyp", "adtyp", "damn", "damd")]


class _PerMonst(C.Structure):  # include/permonst.h
    _fields_ = [
        ("mname", C.c_char_p), ("mlet", C.c_byte), ("mlevel", C.c_byte), ("mmove", C.c_byte),
        ("ac", C.c_byte), ("mr", C.c_byte), ("maligntyp", C.c_byte), ("geno", C.c_ushort),
        ("mattk", _Attack * 6), ("cwt", C.c_ushort), ("cnutrit", C.c_ushort),
        *[(f, C.c_ubyte) for f in ("msound", "msize", "mresists", "mconveys")],
        ("mflags1", C.c_ulong), ("mflags2", C.c_ulong), ("mflags3", C.c_ushort),
        ("difficulty", C.c_ubyte), ("mcolor", C.c_ubyte),
    ]


class _ObjClass(C.Structure):  # include/objclass.h; its 17 bitfield bits fill 3 bytes
    _fields_ = [
        ("oc_name_idx", C.c_short), ("oc_descr_idx", C.c_short), ("oc_uname", C.c_char_p),
        ("bits", C.c_ubyte * 3), ("oc_subtyp", C.c_byte), ("oc_oprop", C.c_ubyte),
        ("oc_class", C.c_byte), ("oc_delay", C.c_byte), ("oc_color", C.c_ubyte),
        ("oc_prob", C.c_short), ("oc_weight", C.c_ushort), ("oc_cost", C.c_short),
        ("oc_wsdam", C.c_byte), ("oc_wldam", C.c_byte), ("oc_oc1", C.c_byte), ("oc_oc2", C.c_byte),
        ("oc_nutrition", C.c_ushort),
    ]


class _ObjDescr(C.Structure):
    _fields_ = [("oc_name", C.c_char_p), ("oc_descr", C.c_char_p)]


def _text(b):
    return b.decode("latin-1") if b else None


def read_tables():
    """(OBJECTS, MONSTERS) as written to codehack_tables.py, read from the engine library."""
    assert C.sizeof(_PerMonst) == 72 and C.sizeof(_ObjClass) == 40, "engine struct layout changed"
    lib = _engine.load_library()
    mons = (_PerMonst * glyphs.NUMMONS).in_dll(lib, "nh_tmpl_mons")
    objs = (_ObjClass * glyphs.NUM_OBJECTS).in_dll(lib, "nh_tmpl_objects")
    descr = (_ObjDescr * glyphs.NUM_OBJECTS).in_dll(lib, "nh_tmpl_obj_descr")
    assert tuple(_text(m.mname) for m in mons) == glyphs.MONSTER_NAMES
    names = [(_text(d.oc_name), _text(d.oc_descr), o.oc_class) for d, o in zip(descr, objs)]
    assert names == OBJECT_TABLE
    objects = tuple((o.oc_subtyp, o.oc_oc1, o.oc_nutrition, o.oc_weight) for o in objs)
    monsters = tuple((m.mlet, m.difficulty, m.ac, m.cnutrit, m.cwt) for m in mons)
    return objects, monsters


def _rows(rows):
    text = ", ".join(f"({','.join(map(str, r))})" for r in rows)
    return textwrap.indent(textwrap.fill(text, 96, break_on_hyphens=False), "    ")


def main(out):
    objects, monsters = read_tables()
    pathlib.Path(out).write_text(
        '"""GENERATED by vendor/tools/gen_codehack_tables.py from libnethack.so; do not edit.\n\n'
        "OBJECTS[otyp] = (oc_subtyp, oc_oc1, oc_nutrition, oc_weight)\n"
        'MONSTERS[mon] = (mlet, difficulty, ac, cnutrit, cwt)\n"""\n\n'
        f"OBJECTS = (\n{_rows(objects)},\n)\n\nMONSTERS = (\n{_rows(monsters)},\n)\n"
    )
    print(f"wrote {len(objects)} objects, {len(monsters)} monsters -> {out}")


if __name__ == "__main__":
    main(sys.argv[1])
